INSERT INTO about (image, title, description, seo_description, seo_title, language)
SELECT image, 'Кой е MSc. Dt. Mehmet Taş?',
'<p>Зъболекарят Мехмет Таш е роден през 1986 г. в Елбистан, област Кахраманмараш. Завършил е основното и средното си образование в Мерсин. През 2004 г. е приет във Факултета по дентална медицина на Истанбулския университет и се дипломира в същия факултет през 2009 г. През 2010 г. отбива военната си служба в Токат като младши лейтенант.</p>
<p>След дипломирането си работи около две години като зъболекар в частна болница Tem. Той е един от учредителите на частната поликлиника по орално и дентално здраве Denttek, работеща от 2012 г. През 2020 г. завършва магистърска степен (Master) по орална хирургия и имплантология в университета UniCamillus в Италия.</p>
<p>Член е на Дружеството &laquo;Академия по естетична дентална медицина&raquo; и на OSSEDER. Работи основно в областта на имплантната хирургия, естетичната дентална медицина и дизайна на усмивка, както и приложението на ботулинов токсин в дъвкателния мускул. Владее английски език. Интересува се от дентална фотография; женен е и има едно дете.</p>
<h2>Образование и професионален път</h2>
<table>
<thead><tr><th>Година</th><th>Етап</th></tr></thead>
<tbody>
<tr><td>2004–2009</td><td>Истанбулски университет, Факултет по дентална медицина — бакалавърско образование и дипломиране</td></tr>
<tr><td>2010</td><td>Военна служба (Токат, младши лейтенант)</td></tr>
<tr><td>2010–2012</td><td>Частна болница Tem — зъболекар</td></tr>
<tr><td>2012</td><td>Частна поликлиника по орално и дентално здраве Denttek — учредител</td></tr>
<tr><td>2020</td><td>Университет UniCamillus (Италия) — магистратура по орална хирургия и имплантология</td></tr>
</tbody>
</table>
<h2>Професионални членства и области на интерес</h2>
<ul>
<li>Членство в Дружеството &laquo;Академия по естетична дентална медицина&raquo;</li>
<li>Членство в OSSEDER (Дружество по остеоинтеграция)</li>
<li>Имплантна хирургия и планиране на сложни хирургични случаи</li>
<li>Естетична дентална медицина и дизайн на усмивка</li>
<li>Ботокс на дъвкателния мускул — приложения при стискане и скърцане със зъби</li>
<li>Дентална фотография и документиране на клинични случаи</li>
</ul>
<h2>Клиничен подход</h2>
<p>В денталната медицина едно и също решение не е правилно за всички. При двама души с едно и също оплакване планът може да е различен, защото останалата здрава зъбна тъкан, поддръжката от венеца и костта, оклузалното съотношение, общото здравословно състояние и навиците за ежедневна грижа се различават от човек до човек.</p>
<p>Затова решението за лечение се взема чрез съвместна оценка на изслушаното оплакване, медицинската и дентална анамнеза, клиничния преглед и само на онези образни изследвания, които са преценени като необходими. Целта на всяка приложима възможност, съществените ѝ ползи и рискове, алтернативите и възможните последици от оставането без лечение се обсъждат по разбираем начин. Информираното съгласие не е само подпис; то е процес на разбираемо осведомяване и възможност да зададете въпроси.</p>
<p>При обширни лечения процедурите се разделят на етапи: първо контрол на спешността и инфекцията, след това спиране на заболяването и осигуряване на основното здраве на венците, после окончателните възстановителни, хирургични или протетични етапи и накрая редът на грижа и контрол. За подробности относно процеса можете да разгледате страницата <a href="/bg/tedavi-plani-ve-surec/">План на лечението и протичане</a>, а за това какво се оценява при първия преглед — <a href="/bg/ilk-dis-muayenesi-tedavi-planlamasi/">Първи дентален преглед и планиране на лечението</a>.</p>
<h2>Нашият лекарски екип</h2>
<p>В клиниката ни работят лекари в областта на имплантологията и оралната хирургия, ендодонтията, детската дентална медицина, ортодонтията, както и възстановителното лечение и протезирането. Всички лечения в областта на денталната медицина се извършват в рамките на нашата клиника. За целия ни лекарски състав: <a href="https://denttek.com.tr/hekimlerimiz/" target="_blank" rel="noopener">Частна клиника Denttek — Нашите лекари</a></p>
<h2>Често задавани въпроси</h2>
<p><strong>В кои области работи MSc. Dt. Mehmet Taş?</strong><br>Работи основно в областта на имплантната хирургия, оралната хирургия и естетичната дентална медицина. Процедурите в областта на ендодонтията, детската дентална медицина, ортодонтията, както и възстановителното лечение и протезирането, се извършват съвместно със съответните лекари в клиниката.</p>
<p><strong>В коя област е магистратурата?</strong><br>Завършена е в университета UniCamillus в Италия в областта на оралната хирургия и имплантологията (2020 г.).</p>
<p><strong>Ботоксът на дъвкателния мускул част ли е от денталната медицина?</strong><br>Да. При хора, при които поради стискане и скърцане със зъби (бруксизъм) се наблюдава свръхнатоварване и уголемяване на дъвкателния мускул, приложението на ботулинов токсин е възможност за лечение, насочена към областта на челюстта и лицето. Решението се взема, като се разглеждат заедно оценката на оклузията, прегледът на мускулите и ставата и находките от износване, и в повечето случаи се преценява заедно с възможности като нощна шина.</p>
<p><strong>Мога ли да се обърна за второ мнение?</strong><br>Да. Получаването на второ мнение е право на пациента. Носенето на наличните рентгенови снимки, доклади и записи от лечението улеснява оценката.</p>
<p><strong>Възможен ли е разговор на английски език?</strong><br>Да, лекарят владее английски език.</p>
<p><strong>Как се съхраняват записите за моето лечение?</strong><br>Сведенията, получени в хода на прегледа, образната диагностика и лечението, са чувствителни лични данни. С каква цел се обработват и какви права имате, е обяснено в <a href="/bg/sayfa/kvkk-aydinlatma-metni">информацията за защита на личните данни</a>.</p>
<h2>Местна оценка</h2>
<p>В нашата клиника на границата между Бейликдюзю и Есенюрт планът на лечение се изготвя чрез съвместна оценка на клиничния преглед, необходимите образни изследвания и очакванията на пациента, след което се споделя с него.</p>
<p><a href="/bg/tedaviler">Видове лечение</a> &middot; <a href="/bg/implant/">Имплантно лечение</a> &middot; <a href="/bg/estetik/">Естетична дентална медицина</a> &middot; <a href="/bg/iletisim">Час и контакти</a></p>',
'Запознайте се с образованието на д-р Мехмет Таш, магистратурата му по орална хирургия и имплантология, клиничния му опит и подхода му към лечението.',
'Кой е MSc. Dt. Mehmet Taş? | Образование и клиничен подход',
'BG' FROM about WHERE language = 'TR';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Информация за защита на личните данни',
'<p>Настоящата информация е изготвена от Dt. Mehmet Taş в качеството му на администратор на лични данни съгласно турския Закон № 6698 за защита на личните данни (&bdquo;KVKK&ldquo;) и се отнася до обработването на личните данни на лицата, които използват формуляра за контакт и заявяване на час в сайта dtmehmettas.com.tr.</p>
<h2>Администратор на данните</h2>
<p>Dt. Mehmet Taş — Cumhuriyet Mah. Nazım Hikmet Blv. No: 89/2, Esenyurt / İstanbul. Електронна поща: info@dtmehmettas.com.tr, телефон: +90 543 558 85 19.</p>
<h2>Обработвани лични данни</h2>
<p>Чрез формуляра за контакт обработваме единствено Вашето име и фамилия, телефонен номер, адрес на електронна поща (по желание) и сведенията, въведени в полето за съобщение. Чрез този формуляр не се изискват здравни данни, диагнози или сведения за лечение; не препоръчваме въвеждането на такава информация в полето за съобщение.</p>
<h2>Цели на обработването</h2>
<p>Вашите лични данни се обработват за следните цели: приемане на запитвания за контакт и заявки за час, отговор на Вашето запитване, уведомяване за организацията на часа и водене на регистър на запитванията. Данните Ви не се използват за рекламни или маркетингови цели и не се предоставят на трети лица с търговска цел.</p>
<h2>Правно основание и начин на събиране</h2>
<p>Данните Ви се събират по електронен път чрез формуляра в сайта и се обработват на правните основания, посочени в чл. 5 от Закона KVKK, а именно че обработването е &bdquo;пряко свързано със сключването или изпълнението на договор&ldquo; и че е &bdquo;необходимо за законните интереси на администратора, при условие че не се засягат основните права и свободи на субекта на данни&ldquo;.</p>
<h2>Предоставяне на данни</h2>
<p>Данните от формуляра се съхраняват при доставчика на хостинг услугата, на който работи сайтът. Без законово задължение те не се предоставят на трети лица в страната или в чужбина.</p>
<h2>Срок на съхранение</h2>
<p>Данните, свързани със запитване за контакт, се съхраняват най-много една година след приключване на случая, след което се изтриват или анонимизират. Ако от запитването възникне пациентско досие, се прилагат сроковете за съхранение, предвидени в здравното законодателство.</p>
<h2>Вашите права като субект на данни</h2>
<p>Съгласно чл. 11 от Закона KVKK имате право: да узнаете дали личните Ви данни се обработват; да поискате информация, ако са били обработвани; да научите целта на обработването и дали данните се използват в съответствие с тази цел; да узнаете третите лица, на които данните са предоставени; да поискате поправка при непълно или погрешно обработване; да поискате изтриване или унищожаване на данните; да поискате третите лица, на които данните са предоставени, да бъдат уведомени за тези действия; да възразите срещу неблагоприятен за Вас резултат, възникнал изключително вследствие на автоматизиран анализ; както и да поискате обезщетение, ако неправомерното обработване Ви е причинило вреда. Можете да отправяте исканията си писмено на посочените по-горе данни за контакт; отговор ще бъде даден най-късно в рамките на 30 дни.</p>
<p><em>Настоящият български текст има информативен характер. В случай на несъответствие обвързваща е турската версия на тази информация.</em></p>
<p><em>Последна актуализация: 21.09.2026</em></p>',
'Информация за защита на личните данни, събирани чрез формуляра за контакт и заявяване на час в сайта dtmehmettas.com.tr.',
'Защита на личните данни | MSc. Dt. Mehmet Taş',
'BG' FROM pages WHERE link = 'kvkk-aydinlatma-metni';
